// Signs Android release builds (APK and Play Store AAB) with Havana's private upload key, kept OUTSIDE the
// repo at ~/havana-signing/keystore.properties (storeFile, storePassword, keyAlias, keyPassword).
// Set HAVANA_KEYSTORE_PROPERTIES to use another path. Without the file, release builds fall back to the
// debug key so other machines can still build test APKs.
// `android/` is regenerated by `expo prebuild`, so the change lives here instead of in build.gradle.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARK = '// havana-release-signing';

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    let gradle = mod.modResults.contents;
    if (gradle.includes(MARK)) return mod;
    gradle = gradle.replace(
      /\nandroid \{/,
      `
${MARK}
def havanaKeys = new File(System.getenv('HAVANA_KEYSTORE_PROPERTIES') ?: "\${System.getProperty('user.home')}/havana-signing/keystore.properties")
def havanaProps = new Properties()
if (havanaKeys.exists()) havanaKeys.withInputStream { havanaProps.load(it) }

android {`,
    );
    gradle = gradle.replace(
      /signingConfigs \{\n/,
      `signingConfigs {
        release {
            if (havanaKeys.exists()) {
                storeFile file(havanaProps['storeFile'])
                storePassword havanaProps['storePassword']
                keyAlias havanaProps['keyAlias']
                keyPassword havanaProps['keyPassword']
            }
        }
`,
    );
    gradle = gradle.replace(
      /(release \{\n(?:\s*\/\/.*\n)*\s*)signingConfig signingConfigs\.debug/,
      '$1signingConfig havanaKeys.exists() ? signingConfigs.release : signingConfigs.debug',
    );
    mod.modResults.contents = gradle;
    return mod;
  });
};
